      <rect x="3" y="35" width="34" height="3" rx="1.5" />
    </svg>
  );
}

function ProgressDots({ current }: { current: number }) {
  return (
    <div className="flex items-center justify-center gap-2">
      {[0, 1, 2].map((i) => (
        <motion.div
          key={i}
          animate={{
            width: i === current ? 32 : 8,
